<?php include __DIR__.'/start.php';?><section class="narrow"><p class="eyebrow"><?=me(__('manor.begin_your_occasion'))?></p><h1><?=me(__('manor.make_an_enquiry'))?></h1><p><?=me(__('manor.select_your_preferred_space_and_london_dates_this_creates_a_draft'))?></p><?php if(!$settings['flags']['enquiries']||!$settings['flags']['venues']):?><p><?=me(__('manor.enquiries_are_currently_closed'))?></p><?php else:?><form method="post" action="/manor/enquire"><?=csrf()?><label><?=me(__('manor.space'))?><select name="unit_id" required><?php foreach($units as $u):try{\App\Manor\Settings::mode($u['mode']);}catch(\DomainException){continue;}if(in_array($u['mode'],['BUILDING','FLOOR'],true))continue;?><option value="<?=me($u['id'])?>" <?=($_GET['unit']??'')===$u['id']?'selected':''?>><?=me($u['name'])?></option><?php endforeach?></select></label><div class="grid"><?=field('start',__('manor.start_europe_london'),'','datetime-local')?><?=field('end',__('manor.end_europe_london'),'','datetime-local')?></div><?=field('guests',__('manor.expected_attendance'),'1','number')?><?=field('name',__('manor.your_name'))?><?=field('email',__('manor.email_address'),'','email')?><?=field('phone',__('manor.phone_number'),'','tel',false)?><label><?=me(__('manor.event_details'))?><textarea name="details" maxlength="10000" required></textarea></label><details><summary><?=me(__('manor.privacy_notice_booking_terms'))?></summary><p><?=me($settings['privacy'])?></p><p><?=me($settings['terms'])?></p></details><label class="check"><input type="checkbox" name="consent" value="1" required><?=me($settings['consent'])?></label><label class="honeypot"><?=me(__('manor.leave_blank'))?><input name="website" tabindex="-1" autocomplete="off"></label><button><?=me(__('manor.create_draft_enquiry'))?></button></form><?php endif?></section><?php include __DIR__.'/end.php';?>
